def dedupe_logs(apps, schema_editor):
    """Collapse pre-existing duplicate day logs before the unique constraint lands.

    Creating a log used to append rather than update, so a day could hold several
    rows. The newest is kept because it is what the athlete last typed and believed
    they were editing.
    """
    DailyLog = apps.get_model("journal", "DailyLog")
    seen = set()
    for row in DailyLog.objects.order_by("athlete_id", "log_date", "-created_at"):
        key = (row.athlete_id, row.log_date)
        if key in seen:
            row.delete()
        else:
            seen.add(key)


